    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = ""
        for (ch in binary_string) {
            if (ch == '0' || ch == '1') {
                cleaned += ch.toString()
            }
        }
        binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        var zeroes: Int64 = 0
        var ones: Int64 = 0

        for (ch in binary_string) {
            if (ch == '0') {
                zeroes += 1
            } else if (ch == '1') {
                ones += 1
            }
        }

        let length = zeroes + ones
        let result = HashMap<String, Float64>()
        if (length == 0) {
            result["Zeroes"] = 0.0
            result["Ones"] = 0.0
        } else {
            result["Zeroes"] = Float64(zeroes) / Float64(length)
            result["Ones"] = Float64(ones) / Float64(length)
        }
        result["Bit length"] = Float64(length)
        return result
    }

    public func convert_to_ascii(): String {
        var output = ""
        var value: Int32 = 0
        var bits: Int32 = 0

        for (ch in binary_string) {
            value = value * 2 + (if (ch == '1') 1 else 0)
            bits += 1
            if (bits == 8) {
                output += Rune(value).toString()
                value = 0
                bits = 0
            }
        }
        return output
    }

    public func convert_to_utf8(): String {
        var output = ""
        var bytes: Array<Int32> = []
        var value: Int32 = 0
        var bits: Int32 = 0

        for (ch in binary_string) {
            value = value * 2 + (if (ch == '1') 1 else 0)
            bits += 1
            if (bits == 8) {
                bytes.append(value)
                value = 0
                bits = 0
            }
        }

        var i = 0
        while (i < bytes.size) {
            let first = bytes[i]
            var codePoint: Int32 = 0
            var extraBytes: Int32 = 0

            if (first < 0x80) {
                codePoint = first
            } else if (first >= 0xC2 && first <= 0xDF) {
                codePoint = first & 0x1F
                extraBytes = 1
            } else if (first >= 0xE0 && first <= 0xEF) {
                codePoint = first & 0x0F
                extraBytes = 2
            } else if (first >= 0xF0 && first <= 0xF4) {
                codePoint = first & 0x07
                extraBytes = 3
            } else {
                output += Rune(0xFFFD).toString()
                i += 1
                continue
            }

            if (i + extraBytes >= bytes.size) {
                output += Rune(0xFFFD).toString()
                break
            }

            var valid = true
            var j: Int32 = 1
            while (j <= extraBytes) {
                let next = bytes[i + j]
                if (next < 0x80 || next > 0xBF) {
                    valid = false
                    break
                }
                codePoint = (codePoint << 6) | (next & 0x3F)
                j += 1
            }

            if (valid) {
                output += Rune(codePoint).toString()
                i += extraBytes + 1
            } else {
                output += Rune(0xFFFD).toString()
                i += 1
            }
        }

        return output
    }
