    /*
    This class implements the Boyer-Moore algorithm for searching for a
    pattern in a string.
    */

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        var index: Int64 = this.patLen - 1
        while (index >= 0) {
            if (this.pattern[index].toString() == char) {
                return index
            }
            index -= 1
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var index: Int64 = this.patLen - 1
        while (index >= 0) {
            if (this.pattern[index].toString() !=
                this.text[currentPos + index].toString()) {
                return index
            }
            index -= 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>()

        if (this.patLen == 0) {
            var position: Int64 = 0
            while (position <= this.textLen) {
                positions.add(position)
                position += 1
            }
            return positions
        }

        var currentPos: Int64 = 0
        while (currentPos + this.patLen <= this.textLen) {
            let mismatchIndex = this.mismatch_in_text(currentPos)

