                positions.add(currentPos)
                currentPos += 1
            } else {
                let textChar = this.text[currentPos + mismatchIndex].toString()
                let patternIndex = this.match_in_pattern(textChar)
                var shift = mismatchIndex - patternIndex
                if (shift < 1) {
                    shift = 1
                }
                currentPos += shift
            }
        }

        return positions
    }
